#!/usr/bin/env sage
"""Search a regular A5 matching orbit for a one-dimensional quadratic trade."""


# This file was *autogenerated* from the file notes/2026-07-26-c665-a5-large-field-falsifier.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_5 = Integer(5); _sage_const_60 = Integer(60); _sage_const_64 = Integer(64); _sage_const_59 = Integer(59)
import argparse
import importlib.util
import itertools
import random
from pathlib import Path

from sage.all import GF, matrix


HERE = Path(__file__).resolve().parent


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


BASE = load("c665_base", HERE / "2026-07-26-c665-balanced-matching-completeness.py")
REPLAY = load(
    "c665_replay",
    HERE / "2026-07-26-c665-balanced-matching-completeness-replay.py",
)


def compose(g, h):
    return tuple(g[h[i]] for i in range(len(g)))


def generated_group(generators):
    identity = tuple(range(len(generators[_sage_const_0 ])))
    answer = {identity}
    frontier = [identity]
    while frontier:
        current = frontier.pop()
        for generator in generators:
            product = compose(generator, current)
            if product not in answer:
                answer.add(product)
                frontier.append(product)
    return answer


def matching_orbit(generators, matching):
    answer = {matching}
    frontier = [matching]
    while frontier:
        current = frontier.pop()
        for generator in generators:
            transformed = BASE.image(generator, current)
            if transformed not in answer:
                answer.add(transformed)
                frontier.append(transformed)
    return sorted(answer)


def standard_generators(q):
    translation = tuple(BASE.mobius((_sage_const_1 , _sage_const_1 , _sage_const_0 , _sage_const_1 ), x, q) for x in range(q + _sage_const_1 ))
    inversion = tuple(BASE.mobius((_sage_const_0 , -_sage_const_1 , _sage_const_1 , _sage_const_0 ), x, q) for x in range(q + _sage_const_1 ))
    squares = {x * x % q for x in range(_sage_const_1 , q)}
    nonsquare = next(x for x in range(_sage_const_2 , q) if x not in squares)
    dilation = tuple(BASE.mobius((nonsquare, _sage_const_0 , _sage_const_0 , _sage_const_1 ), x, q) for x in range(q + _sage_const_1 ))
    return translation, inversion, dilation


def a5_subgroup(q):
    involution = tuple(BASE.mobius((_sage_const_0 , -_sage_const_1 , _sage_const_1 , _sage_const_0 ), x, q) for x in range(q + _sage_const_1 ))
    for a in range(q):
        for b in range(_sage_const_1 , q):
            d = (_sage_const_1  - a) % q
            c = (a * d - _sage_const_1 ) * pow(b, -_sage_const_1 , q) % q
            order_three = tuple(BASE.mobius((a, b, c, d), x, q) for x in range(q + _sage_const_1 ))
            if BASE.permutation_order(order_three) != _sage_const_3 :
                continue
            if BASE.permutation_order(compose(involution, order_three)) != _sage_const_5 :
                continue
            subgroup = generated_group((involution, order_three))
            if len(subgroup) == _sage_const_60 :
                return subgroup
    raise RuntimeError("no A5 subgroup found")


def regular_matching(subgroup, q):
    base = _sage_const_0 
    images = {g[base]: g for g in subgroup}
    assert len(images) == q + _sage_const_1 
    involution = next(g for g in subgroup if BASE.permutation_order(g) == _sage_const_2 )
    partner_at_base = involution[base]
    edges = {
        tuple(sorted((point, g[partner_at_base])))
        for point, g in images.items()
    }
    matching = tuple(sorted(edges))
    assert len(matching) == (q + _sage_const_1 ) // _sage_const_2 
    assert len({endpoint for edge in matching for endpoint in edge}) == q + _sage_const_1 
    assert all(BASE.image(g, matching) == matching for g in subgroup)
    return matching


def evaluation_rows(orbit, q):
    field = GF(q)
    base_product = REPLAY.secant_product(orbit[_sage_const_0 ], q)
    degree = (q - _sage_const_3 ) // _sage_const_2 
    points = []
    for matching in orbit:
        product = REPLAY.secant_product(matching, q)
        difference = {
            exponent: (product.get(exponent, _sage_const_0 ) - base_product.get(exponent, _sage_const_0 )) % q
            for exponent in set(product) | set(base_product)
        }
        points.append(REPLAY.quotient_coefficients(difference, degree, q))
    affine = matrix(
        field,
        [[_sage_const_1 ] * len(orbit)] + [list(column) for column in zip(*points)],
    )
    return affine.row_space().basis_matrix()


def sampled_square_rank(linear, target_rank, seed):
    pairs = list(
        itertools.combinations_with_replacement(range(linear.nrows()), _sage_const_2 )
    )
    random.Random(seed).shuffle(pairs)
    selected = pairs[: target_rank + _sage_const_64 ]
    square = matrix(
        linear.base_ring(),
        [
            linear.row(i).pairwise_product(linear.row(j))
            for i, j in selected
        ],
    )
    return square.rank(), len(selected)


def translation_norm_ranks(linear, orbit, sheets, translation, q):
    unseen = set(orbit)
    translation_orbits = []
    while unseen:
        matching = min(unseen)
        part = []
        current = matching
        while current not in part:
            part.append(current)
            current = BASE.image(translation, current)
        assert len(part) == q
        translation_orbits.append(part)
        unseen -= set(part)
    orbit_index = {matching: i for i, matching in enumerate(orbit)}
    norm_images = matrix(
        linear.base_ring(),
        [
            [
                sum(
                    linear[i, orbit_index[matching]]
                    * linear[j, orbit_index[matching]]
                    for matching in part
                )
                for part in translation_orbits
            ]
            for i in range(linear.nrows())
            for j in range(i, linear.nrows())
        ],
    )
    sheet_sets = [set(sheet) for sheet in sheets]
    orbit_sheet = [
        next(i for i, sheet_set in enumerate(sheet_sets) if part[_sage_const_0 ] in sheet_set)
        for part in translation_orbits
    ]
    sheet_ranks = [
        norm_images[:, [j for j, value in enumerate(orbit_sheet) if value == i]].rank()
        for i in range(_sage_const_2 )
    ]
    return sheet_ranks, norm_images.rank()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--q", type=int, default=_sage_const_59 )
    parser.add_argument("--seed", type=int, default=_sage_const_0 )
    args = parser.parse_args()
    q = args.q
    assert q % _sage_const_2  == _sage_const_1  and q + _sage_const_1  == _sage_const_60 

    subgroup = a5_subgroup(q)
    matching = regular_matching(subgroup, q)
    translation, inversion, dilation = standard_generators(q)
    special = matching_orbit((translation, inversion), matching)
    full = matching_orbit((translation, inversion, dilation), matching)
    assert len(full) == _sage_const_2  * len(special)
    other_sheet = sorted(set(full) - set(special))
    linear = evaluation_rows(full, q)
    target_rank = len(full) - _sage_const_1 
    rank, sampled_rows = sampled_square_rank(linear, target_rank, args.seed)
    sheet_norm_ranks, joint_norm_rank = translation_norm_ranks(
        linear, full, (special, other_sheet), translation, q
    )
    print(
        {
            "q": q,
            "a5_order": len(subgroup),
            "sheet_size": len(special),
            "orbit_size": len(full),
            "lambda": len(special) // q,
            "affine_rank": linear.nrows(),
            "sampled_quadratic_rows": sampled_rows,
            "sampled_square_rank": rank,
            "unique_trade_if_rank": target_rank,
            "sheet_norm_ranks": sheet_norm_ranks,
            "joint_norm_rank": joint_norm_rank,
        }
    )


if __name__ == "__main__":
    main()

